const c = msg.payload.current;
if (!c || c.temperature_2m === undefined) {
    node.error('Dato inválido o null', msg);
    return null;
}
msg.internal = {
    deviceId: 'MICROCOM-CASTELLON-001',
    value: c.temperature_2m,
    timestamp: c.time + ':00Z',
    source: 'open-meteo'
};
return msg;

const d = msg.internal;
const ctx = global.get('deviceStatus') || {};
const prev = ctx[d.deviceId];
const tipoIncidencia = (prev && d.value < prev.value) ? 1 : 0;
msg.payload = JSON.stringify({
    id: d.deviceId,
    type: 'WaterMeter',
    TimeInstant: { type: 'DateTime', value: d.timestamp },
    serialNumber: { type: 'Text', value: d.deviceId },
    vol: { type: 'Number', value: d.value },
    waterConsumption: { type: 'Number', value: Math.round(d.value * 1000) },
    maxWaterFlow: { type: 'Number', value: 0 },
    battery: { type: 'Number', value: 0.85 },
    batteryState: { type: 'Text', value: 'ok' },
    hasTamperAlert: { type: 'Boolean', value: false },
    category: { type: 'Text', value: 'cold' },
    tipoIncidencia: tipoIncidencia,
    source: d.source
});
ctx[d.deviceId] = {
    value: d.value,
    timestamp: d.timestamp,
    status: 'ok',
    errors: (ctx[d.deviceId] ? ctx[d.deviceId].errors : 0)
};
global.set('deviceStatus', ctx);
msg.topic = 'smartvillages/watermeter/microcom';
return msg;

const deviceId = 'MICROCOM-CASTELLON-001';
const queue = global.get('retryQueue') || {};
if (!queue[deviceId]) {
    queue[deviceId] = { attempts: 0, lastError: msg.error.message, ts: Date.now() };
}
queue[deviceId].attempts++;
const ctx = global.get('deviceStatus') || {};
if (!ctx[deviceId]) ctx[deviceId] = { value: null, timestamp: null, errors: 0 };
ctx[deviceId].status = 'error';
ctx[deviceId].errors = queue[deviceId].attempts;
ctx[deviceId].lastError = msg.error.message;
global.set('deviceStatus', ctx);
if (queue[deviceId].attempts >= 3) {
    node.warn('MAX REINTENTOS alcanzado para ' + deviceId);
    queue[deviceId] = null;
    global.set('retryQueue', queue);
    const logs = global.get('errorLog') || [];
    logs.push({ deviceId, error: msg.error.message, ts: new Date().toISOString() });
    if (logs.length > 100) logs.shift();
    global.set('errorLog', logs);
    return null;
}
global.set('retryQueue', queue);
node.warn('Error capturado · Reintento ' + queue[deviceId].attempts + '/3 en 5 min');
setTimeout(() => { node.send(msg); }, 5 * 60 * 1000);
return null;
